using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using ProMaxx2.QA.Domain.Execution;using ProMaxx2.QA.Domain.Identity;using ProMaxx2.QA.Domain.Projects;using ProMaxx2.QA.Domain.Releases;using ProMaxx2.QA.Domain.TestManagement;
namespace ProMaxx2.QA.Infrastructure.Persistence;
public sealed class TestEnvironmentConfiguration:IEntityTypeConfiguration<TestEnvironment>{public void Configure(EntityTypeBuilder<TestEnvironment>b){b.ToTable("TestEnvironments");b.HasKey(x=>x.TestEnvironmentId);b.Property(x=>x.TestEnvironmentId).HasDefaultValueSql("NEWSEQUENTIALID()");b.Property(x=>x.EnvironmentName).HasMaxLength(150).IsRequired();b.Property(x=>x.BaseUrl).HasMaxLength(500);b.HasOne<Project>().WithMany().HasForeignKey(x=>x.ProjectId).OnDelete(DeleteBehavior.Restrict);}}
public sealed class TestCycleConfiguration:IEntityTypeConfiguration<TestCycle>{public void Configure(EntityTypeBuilder<TestCycle>b){b.ToTable("TestCycles");b.HasKey(x=>x.TestCycleId);b.Property(x=>x.TestCycleId).HasDefaultValueSql("NEWSEQUENTIALID()");b.Property(x=>x.CycleCode).HasMaxLength(100).IsRequired();b.Property(x=>x.CycleName).HasMaxLength(300).IsRequired();b.Property(x=>x.CycleType).HasMaxLength(50);b.Property(x=>x.Status).HasMaxLength(30);b.Property(x=>x.StartDate).HasPrecision(0);b.Property(x=>x.EndDate).HasPrecision(0);b.Property(x=>x.CreatedAt).HasPrecision(0);b.HasIndex(x=>new{x.ProjectId,x.CycleCode}).IsUnique();b.HasOne<Project>().WithMany().HasForeignKey(x=>x.ProjectId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Release>().WithMany().HasForeignKey(x=>x.ReleaseId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Build>().WithMany().HasForeignKey(x=>x.BuildId).OnDelete(DeleteBehavior.Restrict);b.HasOne<TestEnvironment>().WithMany().HasForeignKey(x=>x.EnvironmentId).OnDelete(DeleteBehavior.Restrict);b.HasOne<TestSuite>().WithMany().HasForeignKey(x=>x.TestSuiteId).OnDelete(DeleteBehavior.Restrict);b.HasOne<User>().WithMany().HasForeignKey(x=>x.OwnerUserId).OnDelete(DeleteBehavior.Restrict);}}
public sealed class TestCycleCaseConfiguration:IEntityTypeConfiguration<TestCycleCase>{public void Configure(EntityTypeBuilder<TestCycleCase>b){b.ToTable("TestCycleCases");b.HasKey(x=>x.TestCycleCaseId);b.Property(x=>x.TestCycleCaseId).HasDefaultValueSql("NEWSEQUENTIALID()");b.Property(x=>x.Priority).HasMaxLength(20);b.Property(x=>x.CurrentStatus).HasMaxLength(30);b.HasIndex(x=>new{x.TestCycleId,x.TestCaseId}).IsUnique();b.HasOne(x=>x.Cycle).WithMany(x=>x.Cases).HasForeignKey(x=>x.TestCycleId).OnDelete(DeleteBehavior.Cascade);b.HasOne(x=>x.TestCase).WithMany().HasForeignKey(x=>x.TestCaseId).OnDelete(DeleteBehavior.Restrict);b.HasOne<User>().WithMany().HasForeignKey(x=>x.AssignedTesterUserId).OnDelete(DeleteBehavior.Restrict);}}
public sealed class TestExecutionConfiguration:IEntityTypeConfiguration<TestExecution>{public void Configure(EntityTypeBuilder<TestExecution>b){b.ToTable("TestExecutions");b.HasKey(x=>x.TestExecutionId);b.Property(x=>x.TestExecutionId).HasDefaultValueSql("NEWSEQUENTIALID()");b.Property(x=>x.Status).HasMaxLength(30).IsRequired();b.Property(x=>x.StartedAt).HasPrecision(0);b.Property(x=>x.CompletedAt).HasPrecision(0);b.HasIndex(x=>new{x.TestCycleCaseId,x.ExecutionNo}).IsUnique();b.HasOne(x=>x.CycleCase).WithMany(x=>x.Executions).HasForeignKey(x=>x.TestCycleCaseId).OnDelete(DeleteBehavior.Cascade);b.HasOne<Build>().WithMany().HasForeignKey(x=>x.BuildId).OnDelete(DeleteBehavior.Restrict);b.HasOne<TestEnvironment>().WithMany().HasForeignKey(x=>x.EnvironmentId).OnDelete(DeleteBehavior.Restrict);b.HasOne<User>().WithMany().HasForeignKey(x=>x.TesterUserId).OnDelete(DeleteBehavior.Restrict);}}
public sealed class TestStepResultConfiguration:IEntityTypeConfiguration<TestStepResult>{public void Configure(EntityTypeBuilder<TestStepResult>b){b.ToTable("TestStepResults");b.HasKey(x=>x.TestStepResultId);b.Property(x=>x.TestStepResultId).HasDefaultValueSql("NEWSEQUENTIALID()");b.Property(x=>x.Status).HasMaxLength(30).IsRequired();b.HasOne(x=>x.Execution).WithMany(x=>x.StepResults).HasForeignKey(x=>x.TestExecutionId).OnDelete(DeleteBehavior.Cascade);}}
